import{_ as t,o as a,c as i,a4 as o}from"./chunks/framework.3hqjI0F0.js";const g=JSON.parse('{"title":"Tài Liệu & Kế Hoạch Sử Dụng REA (morluto/rea) Cho Dự Án zca-js","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://softtyos.github.io/zca-js-docs/REA_REVERSE_ENGINEERING_PLAN.html"}],["meta",{"property":"og:url","content":"https://softtyos.github.io/zca-js-docs/REA_REVERSE_ENGINEERING_PLAN.html"}],["meta",{"property":"og:title","content":"Tài Liệu & Kế Hoạch Sử Dụng REA (morluto/rea) Cho Dự Án zca-js"}],["meta",{"property":"og:description","content":"Bộ SDK Zalo API Hiện Đại Cho Node.js, TypeScript & Bun bởi Softtynet Co., Ltd."}]]},"headers":[],"relativePath":"REA_REVERSE_ENGINEERING_PLAN.md","filePath":"REA_REVERSE_ENGINEERING_PLAN.md","lastUpdated":1793046342000}'),n={name:"REA_REVERSE_ENGINEERING_PLAN.md"};function c(s,e,d,l,h,r){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="tai-lieu-ke-hoach-su-dung-rea-morluto-rea-cho-du-an-zca-js" tabindex="-1">Tài Liệu &amp; Kế Hoạch Sử Dụng REA (<code>morluto/rea</code>) Cho Dự Án <code>zca-js</code> <a class="header-anchor" href="#tai-lieu-ke-hoach-su-dung-rea-morluto-rea-cho-du-an-zca-js" aria-label="Permalink to &quot;Tài Liệu &amp; Kế Hoạch Sử Dụng REA (`morluto/rea`) Cho Dự Án `zca-js`&quot;">​</a></h1><p>Tài liệu này là sổ tay kỹ thuật hoàn chỉnh hướng dẫn cài đặt, vận hành bộ công cụ <strong>REA (<code>rea-agents</code>)</strong> (<a href="https://github.com/morluto/rea" target="_blank" rel="noreferrer">github.com/morluto/rea</a> | <a href="https://rea.tools/" target="_blank" rel="noreferrer">rea.tools</a>) và <strong>Kế hoạch 4 giai đoạn</strong> áp dụng REA để dịch ngược các tính năng nâng cao của Zalo Desktop (<code>app.asar</code> + Native Addons) và Zalo Web (<code>chat.zalo.me</code>).</p><hr><h2 id="_1-tong-quan-ve-rea-rea-agents" tabindex="-1">1. Tổng Quan Về REA (<code>rea-agents</code>) <a class="header-anchor" href="#_1-tong-quan-ve-rea-rea-agents" aria-label="Permalink to &quot;1. Tổng Quan Về REA (`rea-agents`)&quot;">​</a></h2><p><strong>REA (Reverse Engineering Assistant)</strong> là một bộ công cụ <strong>CLI + MCP Server</strong> chuyên dụng giúp kết nối các AI Coding Agents (như Antigravity, Claude Code, Cursor, Codex) trực tiếp với các trình dịch ngược phần mềm:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Thành phần mục tiêu</th><th style="text-align:left;">Công cụ REA sử dụng</th><th style="text-align:left;">Ứng dụng trong <code>zca-js</code></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Gói Electron (<code>app.asar</code>)</strong></td><td style="text-align:left;"><code>analyze-javascript-application</code></td><td style="text-align:left;">Giải nén, quét AST, trích xuất bảng <code>commandId</code>, endpoint REST/WebSocket, hằng số mã hóa từ <code>/Applications/Zalo.app/Contents/Resources/app.asar</code>.</td></tr><tr><td style="text-align:left;"><strong>Web App (<code>chat.zalo.me</code>)</strong></td><td style="text-align:left;"><code>analyze-website</code> + HAR Capture</td><td style="text-align:left;">Quét các webpack chunks, WebWorker, WASM (<code>libzproto_wasm_bg.wasm</code>) và phân tích lưu lượng mạng thực tế (<code>.har</code>).</td></tr><tr><td style="text-align:left;"><strong>Cơ sở dữ liệu cục bộ</strong></td><td style="text-align:left;">SQLite Inspector</td><td style="text-align:left;">Kiểm tra cấu trúc bảng <code>ChatContent</code>, <code>message</code>, <code>conversation</code> trong file sao lưu <code>ZDB4.0</code> (<code>.db.crypt</code>) của Zalo Mobile/PC.</td></tr><tr><td style="text-align:left;"><strong>Native Binary (<code>.node</code> / <code>.dylib</code>)</strong></td><td style="text-align:left;">Ghidra / Hopper / IDA Bridge</td><td style="text-align:left;">Dịch ngược mã máy C/C++ trong <code>zcall.node</code>, <code>libzrtc.dylib</code>, <code>zcrypto.node</code> để lấy thuật toán mã hóa media (ZRTP) và chữ ký native.</td></tr></tbody></table><hr><h2 id="_2-cai-đat-cau-hinh-chuan-bi" tabindex="-1">2. Cài Đặt &amp; Cấu Hình Chuẩn Bị <a class="header-anchor" href="#_2-cai-đat-cau-hinh-chuan-bi" aria-label="Permalink to &quot;2. Cài Đặt &amp; Cấu Hình Chuẩn Bị&quot;">​</a></h2><h3 id="_2-1-yeu-cau-he-thong" tabindex="-1">2.1. Yêu cầu hệ thống <a class="header-anchor" href="#_2-1-yeu-cau-he-thong" aria-label="Permalink to &quot;2.1. Yêu cầu hệ thống&quot;">​</a></h3><ol><li><p><strong>Node.js <code>&gt;= 22.19.0</code> hoặc <code>24.x</code></strong> (bắt buộc vì <code>rea-agents</code> sử dụng module native <code>node:sqlite</code> để lập chỉ mục các hàm/symbol khi dịch ngược):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Kiểm tra phiên bản Node hiện tại</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Nếu đang ở Node 20, chuyển sang Node 22+ qua nvm hoặc fnm:</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span></span></code></pre></div></li><li><p><strong>Ứng dụng Zalo Desktop trên macOS</strong>:</p><ul><li>Đường dẫn ASAR: <code>/Applications/Zalo.app/Contents/Resources/app.asar</code></li><li>Đường dẫn Native Addons đã giải nén: <code>/Applications/Zalo.app/Contents/Resources/app.asar.unpacked/</code></li></ul></li><li><p><strong>Trình dịch ngược Binary (tuỳ chọn cho Giai đoạn 1 &amp; 3)</strong>:</p><ul><li><strong>Ghidra</strong> (miễn phí, mã nguồn mở) hoặc <strong>Hopper Disassembler</strong> / <strong>IDA Pro</strong> trên macOS.</li></ul></li></ol><h3 id="_2-2-cai-đat-va-ket-noi-mcp-server" tabindex="-1">2.2. Cài đặt và kết nối MCP Server <a class="header-anchor" href="#_2-2-cai-đat-va-ket-noi-mcp-server" aria-label="Permalink to &quot;2.2. Cài đặt và kết nối MCP Server&quot;">​</a></h3><p>Chạy lệnh khởi tạo tự động của REA để đăng ký MCP server vào trình soạn thảo/AI Agent:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rea-agents@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre></div><p>Hoặc cấu hình thủ công trong <code>mcp_config.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;rea&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rea-agents@latest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="_3-so-tay-cac-lenh-rea-thuc-chien-voi-zalo" tabindex="-1">3. Sổ Tay Các Lệnh REA Thực Chiến Với Zalo <a class="header-anchor" href="#_3-so-tay-cac-lenh-rea-thuc-chien-voi-zalo" aria-label="Permalink to &quot;3. Sổ Tay Các Lệnh REA Thực Chiến Với Zalo&quot;">​</a></h2><h3 id="_3-1-phan-tich-goi-electron-app-asar-cua-zalo-pc" tabindex="-1">3.1. Phân tích gói Electron <code>app.asar</code> của Zalo PC <a class="header-anchor" href="#_3-1-phan-tich-goi-electron-app-asar-cua-zalo-pc" aria-label="Permalink to &quot;3.1. Phân tích gói Electron `app.asar` của Zalo PC&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rea-agents@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analyze-javascript-application</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;/Applications/Zalo.app/Contents/Resources/app.asar&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --json</span></span></code></pre></div><ul><li>Lệnh này giúp lập chỉ mục toàn bộ các webpack modules bên trong <code>app.asar</code> (ví dụ module chứa bảng định tuyến <code>commandId</code> từ <code>10001</code> đến <code>16228</code>, <code>SyncMessageController</code>, <code>BackupMsgController</code>, <code>VoiceCallDomain</code>, v.v.).</li></ul><h3 id="_3-2-phan-tich-truc-tiep-chat-zalo-me" tabindex="-1">3.2. Phân tích trực tiếp <code>chat.zalo.me</code> <a class="header-anchor" href="#_3-2-phan-tich-truc-tiep-chat-zalo-me" aria-label="Permalink to &quot;3.2. Phân tích trực tiếp `chat.zalo.me`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rea-agents@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analyze-website</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://chat.zalo.me</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><h3 id="_3-3-giai-nen-app-asar-ra-thu-muc-tam-đe-tra-cuu-sau-ket-hop-rea" tabindex="-1">3.3. Giải nén <code>app.asar</code> ra thư mục tạm để tra cứu sâu kết hợp REA <a class="header-anchor" href="#_3-3-giai-nen-app-asar-ra-thu-muc-tam-đe-tra-cuu-sau-ket-hop-rea" aria-label="Permalink to &quot;3.3. Giải nén `app.asar` ra thư mục tạm để tra cứu sâu kết hợp REA&quot;">​</a></h3><p>Khi cần kết hợp REA với tìm kiếm mã nguồn trực tiếp:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @electron/asar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;/Applications/Zalo.app/Contents/Resources/app.asar&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;/tmp/zalo-asar-extracted&quot;</span></span></code></pre></div><hr><h2 id="_4-hien-trang-cac-tinh-nang-đa-hoan-thien-100-verified-trong-zca-js" tabindex="-1">4. Hiện Trạng Các Tính Năng Đã Hoàn Thiện (100% Verified) Trong <code>zca-js</code> <a class="header-anchor" href="#_4-hien-trang-cac-tinh-nang-đa-hoan-thien-100-verified-trong-zca-js" aria-label="Permalink to &quot;4. Hiện Trạng Các Tính Năng Đã Hoàn Thiện (100% Verified) Trong `zca-js`&quot;">​</a></h2><p>Trước khi dùng REA cho các tính năng mới, dưới đây là các tính năng <strong>đã được xác minh 100% từ <code>app.asar</code> và tích hợp sẵn vào nhánh <code>lib</code> của <code>zca-js</code></strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Nhóm tính năng</th><th style="text-align:left;">API / Sự kiện trong <code>zca-js</code></th><th style="text-align:left;">Command ID / Giao thức Zalo</th><th style="text-align:left;">Trạng thái</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Lấy bù tin nhắn khi mở lại app (Offline Catch-up)</strong></td><td style="text-align:left;"><code>api.preloadConversations(threadIdLocalMsgId)</code></td><td style="text-align:left;"><code>10053</code> (<code>/api/preloadconvers/get-last-msgs</code>)</td><td style="text-align:left;">✅ Hoàn tất 100%</td></tr><tr><td style="text-align:left;"><strong>Kéo hàng đợi tin nhắn nhỡ qua WebSocket</strong></td><td style="text-align:left;"><code>api.listener.requestOldMessages(threadType, lastMsgId)</code> + sự kiện <code>old_messages</code></td><td style="text-align:left;">WS <code>cmd: 510</code> (User) &amp; <code>cmd: 511</code> (Group), <code>subCmd: 0 | 1</code></td><td style="text-align:left;">✅ Hoàn tất 100%</td></tr><tr><td style="text-align:left;"><strong>Đồng bộ trạng thái đã đọc liên thiết bị</strong></td><td style="text-align:left;">Sự kiện <code>api.listener.on(&quot;unread_cleared&quot;, ...)</code></td><td style="text-align:left;">WS <code>cmd: 504</code> / <code>524</code> (<code>clearUnreads</code>)</td><td style="text-align:left;">✅ Hoàn tất 100%</td></tr><tr><td style="text-align:left;"><strong>Kích hoạt đồng bộ từ điện thoại (Mobile Backup Sync)</strong></td><td style="text-align:left;"><code>api.requestSyncFromPhone()</code>, <code>api.pullMobile()</code>, <code>api.cancelPullMobile()</code></td><td style="text-align:left;"><code>12000</code> (<code>pull_mobile_msg</code>), <code>12700</code> (<code>cancel_pull_mobile_msg</code>)</td><td style="text-align:left;">✅ Hoàn tất 100%</td></tr><tr><td style="text-align:left;"><strong>Lắng nghe tiến trình đồng bộ từ điện thoại</strong></td><td style="text-align:left;">Sự kiện <code>api.listener.on(&quot;sync_event&quot;, ...)</code> (<code>USER_CONFIRM</code>, <code>SYNCMSG_INFO</code>, <code>TRANSFER_ERROR</code>, <code>TRANSFER_AFTER_LOGIN</code>)</td><td style="text-align:left;">WS <code>cmd: 601</code>, <code>act_type: &quot;syncmsgmb&quot;</code> &amp; <code>&quot;transfer_msg&quot;</code></td><td style="text-align:left;">✅ Hoàn tất 100%</td></tr><tr><td style="text-align:left;"><strong>Tải &amp; giải mã gói sao lưu <code>ZDB4.0</code> (<code>.db.crypt</code>)</strong></td><td style="text-align:left;"><code>api.getSyncData()</code>, <code>decryptWithPrivateKey()</code>, <code>deriveZdbAesKey()</code>, <code>decryptZdbBuffer()</code></td><td style="text-align:left;">RSA-2048 PKCS#1 v1.5 + AES-256-CBC 64KB chunk (<code>ZDB4.0</code>)</td><td style="text-align:left;">✅ Hoàn tất 100%</td></tr><tr><td style="text-align:left;"><strong>Quy đổi UID/GID số thuần sang Noised ID 19 số</strong></td><td style="text-align:left;"><code>api.getNoisedIds({ fids, gids })</code> &amp; <code>api.decryptGids(gids)</code></td><td style="text-align:left;"><code>12390</code> (<code>/api/znoise</code>) &amp; <code>12054</code> (<code>/api/gid/decrypt</code>)</td><td style="text-align:left;">✅ Hoàn tất 100%</td></tr><tr><td style="text-align:left;"><strong>Báo hiệu Gọi Điện Thoại (Voice/Video Call Signaling)</strong></td><td style="text-align:left;"><code>api.sendVoiceCall()</code>, <code>api.cancelVoiceCall()</code>, <code>api.endVoiceCall()</code> + sự kiện <code>call_event</code></td><td style="text-align:left;"><code>11300</code> (<code>requestcall</code>), <code>11301</code> (<code>request</code>), <code>11305</code> (<code>cancel</code>), <code>11306</code> (<code>endcall</code>), WS <code>act_type: &quot;voip&quot;</code></td><td style="text-align:left;">✅ Hoàn tất 100%</td></tr></tbody></table><hr><h2 id="_5-ke-hoach-4-giai-đoan-su-dung-rea-cho-cac-tinh-nang-chua-co" tabindex="-1">5. Kế Hoạch 4 Giai Đoạn Sử Dụng REA Cho Các Tính Năng Chưa Có <a class="header-anchor" href="#_5-ke-hoach-4-giai-đoan-su-dung-rea-cho-cac-tinh-nang-chua-co" aria-label="Permalink to &quot;5. Kế Hoạch 4 Giai Đoạn Sử Dụng REA Cho Các Tính Năng Chưa Có&quot;">​</a></h2><p>Dưới đây là lộ trình chi tiết sử dụng <strong>REA</strong> để nghiên cứu và mở khóa 4 nhóm tính năng phức tạp tiếp theo của Zalo:</p><h3 id="giai-đoan-1-giai-ma-media-plane-2-chieu-đam-thoai-am-thanh-rtp-zrtp-thuc-su" tabindex="-1">Giai đoạn 1: Giải mã Media Plane 2 chiều (Đàm thoại âm thanh RTP/ZRTP thực sự) <a class="header-anchor" href="#giai-đoan-1-giai-ma-media-plane-2-chieu-đam-thoai-am-thanh-rtp-zrtp-thuc-su" aria-label="Permalink to &quot;Giai đoạn 1: Giải mã Media Plane 2 chiều (Đàm thoại âm thanh RTP/ZRTP thực sự)&quot;">​</a></h3><ul><li><strong>Vấn đề hiện tại</strong>: <code>api.sendVoiceCall()</code> đã làm đổ chuông điện thoại người nhận và lấy về thành công <code>{ sessId, rtpServer, rtcpServer, zrtpKey, codec }</code>, đồng thời nhận được sự kiện <code>call_event</code> khi người nhận bắt máy (<code>CallEventType.ANSWER</code>). Tuy nhiên, để truyền/nhận giọng nói 2 chiều sau khi bắt máy, Zalo PC không dùng WebRTC của trình duyệt mà uỷ quyền cho native addon <code>zcall.node</code> + <code>libzrtc.dylib</code>.</li><li><strong>Mục tiêu dùng REA</strong>: <ol><li>Dùng REA kết nối với <strong>Ghidra/Hopper</strong> mở 2 file native trong <code>/Applications/Zalo.app/Contents/Resources/app.asar.unpacked/</code>: <ul><li><code>zcall.node</code> (Bridge IPC giữa Electron JS và C++)</li><li><code>libzrtc.dylib</code> (Engine xử lý giao thức UDP RTP/RTCP + mã hóa ZRTP)</li></ul></li><li>Tìm các hàm xuất (exports) liên quan đến <code>initCall</code>, <code>sendDataToNative</code>, <code>recvSignal</code> (đặc biệt khi nhận <code>command: 401</code>, <code>416</code>, <code>402</code> trong <code>app.asar</code>) và <code>InitZRTP</code>.</li><li>Xác định định dạng header gói tin UDP đầu tiên gửi tới <code>rtpServer</code> / <code>rtcpServer</code> (cách đóng gói <code>sessId</code>, <code>callId</code>, <code>zrtpKey</code> và codec Opus payload type).</li><li>Viết module <code>VoiceCallMediaSession</code> bằng <code>node:dgram</code> (UDP socket) trong <code>zca-js</code> để cho phép phát file âm thanh (<code>.wav</code>/<code>.opus</code>) vào cuộc gọi hoặc thu âm luồng thoại của đối phương.</li></ol></li></ul><h3 id="giai-đoan-2-giai-ma-giao-thuc-đong-bo-the-he-2-transfer-sync-v2-webassembly" tabindex="-1">Giai đoạn 2: Giải mã giao thức Đồng bộ thế hệ 2 (<code>Transfer-Sync-V2</code> &amp; WebAssembly) <a class="header-anchor" href="#giai-đoan-2-giai-ma-giao-thuc-đong-bo-the-he-2-transfer-sync-v2-webassembly" aria-label="Permalink to &quot;Giai đoạn 2: Giải mã giao thức Đồng bộ thế hệ 2 (`Transfer-Sync-V2` &amp; WebAssembly)&quot;">​</a></h3><ul><li><strong>Vấn đề hiện tại</strong>: Ngoài luồng <code>pull_mobile_msg</code> (<code>12000</code> - <code>ZDB4.0</code>), các bản Zalo mới đang triển khai song song giao thức <code>/api/transfer-sync-v2/request-sync</code> (command <code>12888</code>) và sự kiện <code>act_type: &quot;transfer_sync2&quot;</code> sử dụng file WebAssembly <code>libzproto_wasm_bg.wasm</code>.</li><li><strong>Mục tiêu dùng REA</strong>: <ol><li>Dùng REA phân tích class <code>SyncController</code> và <code>_processSync2Ctrl</code> trong <code>app.asar</code> để lấy toàn bộ state machine của <code>transfer_sync2</code>.</li><li>Dùng REA + Ghidra (với plugin WASM) hoặc <code>wasm2wat</code> phân tích file <code>libzproto_wasm_bg.wasm</code> để trích xuất schema Protobuf của tham số <code>data</code> trong: <ul><li><code>/api/transfer-sync-v2/request-sync</code> (<code>12888</code>)</li><li><code>/api/transfer-sync-v2/download</code></li></ul></li><li>Tích hợp bộ parser Protobuf thuần TypeScript vào <code>zca-js</code> mà không cần phụ thuộc binary WASM nặng nề.</li></ol></li></ul><h3 id="giai-đoan-3-giai-ma-tin-nhan-ma-hoa-đau-cuoi-chat-e2ee-commands-16000–16201" tabindex="-1">Giai đoạn 3: Giải mã Tin nhắn Mã hóa Đầu cuối (<code>CHAT_E2EE</code>, commands <code>16000</code>–<code>16201</code>) <a class="header-anchor" href="#giai-đoan-3-giai-ma-tin-nhan-ma-hoa-đau-cuoi-chat-e2ee-commands-16000–16201" aria-label="Permalink to &quot;Giai đoạn 3: Giải mã Tin nhắn Mã hóa Đầu cuối (`CHAT_E2EE`, commands `16000`–`16201`)&quot;">​</a></h3><ul><li><strong>Vấn đề hiện tại</strong>: Khi một cuộc trò chuyện bật &quot;Mã hóa đầu cuối (E2EE)&quot;, tin nhắn trả về nằm trong mảng <code>eeMsgs</code> (khi gọi <code>preloadConversations</code>) và sử dụng cụm endpoint <code>/api/e2ee/pc/message/*</code> (<code>16000</code>–<code>16201</code>).</li><li><strong>Mục tiêu dùng REA</strong>: <ol><li>Dùng REA quét toàn bộ các tham chiếu tới <code>16000</code>–<code>16201</code> (<code>getE2eeDomain()</code>, <code>deleteOneOneE2eeMessageV2</code>, <code>EntriesTransferManager</code>) trong <code>app.asar</code>.</li><li>Dùng REA kết nối Ghidra phân tích <code>zcrypto.node</code> để xác định cơ chế trao đổi khoá (Signal Protocol / Double Ratchet hoặc X25519 + AES-GCM của Zalo).</li><li>Bổ sung <code>sendE2EEMessage</code> và bộ giải mã tự động cho <code>eeMsgs</code> trong <code>listen.ts</code> và <code>preloadConversations.ts</code>.</li></ol></li></ul><h3 id="giai-đoan-4-goi-nhom-group-voice-video-call-commands-12433–12447" tabindex="-1">Giai đoạn 4: Gọi Nhóm (<code>Group Voice/Video Call</code>, commands <code>12433</code>–<code>12447</code>) <a class="header-anchor" href="#giai-đoan-4-goi-nhom-group-voice-video-call-commands-12433–12447" aria-label="Permalink to &quot;Giai đoạn 4: Gọi Nhóm (`Group Voice/Video Call`, commands `12433`–`12447`)&quot;">​</a></h3><ul><li><strong>Vấn đề hiện tại</strong>: Từ <code>app.asar</code>, chúng ta đã trích xuất được danh sách đầy đủ các API gọi nhóm: <ul><li><code>12433</code>: <code>/api/voicecall/group/requestcall</code> (<code>{ groupId, callId, typeRequest, data, partners }</code>)</li><li><code>12434</code>: <code>/api/voicecall/group/request</code> (<code>{ calleeId, callId, callType, data, session, partners, groupId }</code>)</li><li><code>12435</code>: <code>/api/voicecall/group/adduser</code></li><li><code>12436</code>: <code>/api/voicecall/group/answer</code></li><li><code>12437</code>: <code>/api/voicecall/group/cancel</code></li><li><code>12438</code>: <code>/api/voicecall/group/endcall</code></li><li><code>12439</code>: <code>/api/voicecall/group/ringring</code></li><li><code>12445</code>: <code>/api/voicecall/group/state</code></li></ul></li><li><strong>Mục tiêu dùng REA</strong>: <ol><li>Dùng tính năng phân tích HAR của REA khi thực hiện 1 cuộc gọi nhóm thực tế trên Zalo PC/Web để bắt chính xác cấu trúc chuỗi JSON bên trong trường <code>data</code> và mảng <code>partners</code>.</li><li>Sau khi có mẫu payload thực tế từ HAR, đóng gói thành các API <code>sendGroupVoiceCall</code>, <code>cancelGroupVoiceCall</code>, <code>endGroupVoiceCall</code> trong <code>zca-js</code>.</li></ol></li></ul>',40)])])}const u=t(n,[["render",c]]);export{g as __pageData,u as default};
